const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const acct = '${GMAIL_USER}';
const vip = '${VIP_SENDERS}'.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const rescue = /int[ée]rim|mission|aide[- ]soignant|\bASH\b|FFAS|alternance|TSSR|\bCDD\b|candidature|entretien|recrut/i;
return $input.all().map(({ json: m }) => {
  const from = m.from?.text || m.from || '';
  const subject = m.subject || '';
  const addr = (from.match(/<([^>]+)>/)?.[1] || from).toLowerCase();
  const text = (m.textPlain || m.text || '').replace(/\s+/g, ' ').slice(0, 1500);
  const h = m.metadata || m.headers || {}; // the IMAP node puts the raw headers under `metadata`
  const mid = String(h['message-id'] || '').replace(/^<|>$/g, '');
  const link = mid ? `https://mail.google.com/mail/?authuser=${encodeURIComponent(acct)}#search/rfc822msgid%3A${encodeURIComponent(mid)}` : '';
  const bulk = 'list-unsubscribe' in h || /bulk|list|junk/i.test(h.precedence || '');
  const isVip = vip.some(v => addr === v || addr.endsWith('@' + v) || addr.endsWith('.' + v));
  const excerpt = text.replace(/https?:\/\/\S+/g, '').replace(/\s+/g, ' ').trim();
  const short = excerpt.length > 220 ? excerpt.slice(0, 220).replace(/\s+\S*$/, '') + '…' : excerpt;
  const base = { from, subject, link, excerpt: short, lu: m.lu === true };
  if (isVip) return { json: { ...base, route: 'vip', msg: `📬 <b>${esc(subject)}</b>\nDe : ${esc(from)}\n→ expéditeur prioritaire` + (short ? `\n<i>${esc(short)}</i>` : '') + (m.lu ? '\n👁️ Lu par Kram' : '') + (link ? `\n<a href="${link}">📧 Ouvrir le mail</a>` : '') } };
  if (bulk && !rescue.test(subject + ' ' + text)) return { json: { ...base, route: 'bruit', kind: 'newsletter' } };
  return { json: { ...base, route: 'ia', body: {
    model: 'openai/gpt-oss-120b',
    reasoning_effort: 'low',
    temperature: 0,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: "Tu tries les mails de Kram, qui cherche : une alternance TSSR (syst\u00e8mes/r\u00e9seaux, Toulouse), des missions d'int\u00e9rim aide-soignant (FFAS/ASH), et des clients pour son activit\u00e9 de prestataire informatique.\n\nIMPORTANT = une personne ou une organisation attend une r\u00e9ponse ou une action de sa part, dans l'un de ces cas : recruteurs, entreprises, \u00e9coles ou organismes de formation (alternance, TSSR) ; agences d'int\u00e9rim, offres de mission ou d'emploi ; clients ou prospects ; administration et finances (France Travail, URSSAF, imp\u00f4ts, banque, assurance) ; rendez-vous ou livraison \u00e0 venir.\nPAS IMPORTANT = tout message automatique qui ne demande rien : newsletters, promotions, r\u00e9seaux sociaux, re\u00e7us, confirmations, changements de conditions, et les notifications de s\u00e9curit\u00e9 courantes (nouvelle connexion, nouvel appareil, application tierce autoris\u00e9e, alerte de s\u00e9curit\u00e9). Une notification de s\u00e9curit\u00e9 n'est importante que si elle annonce un mot de passe ou un e-mail modifi\u00e9, un compte suspendu ou pirat\u00e9.\n\nDans le doute, r\u00e9ponds important=true pour le message d'une personne ou d'une entreprise, et important=false pour un message automatique de plateforme.\nR\u00e9ponds UNIQUEMENT en JSON, raison \u00e9crite en fran\u00e7ais : {\"important\": true|false, \"reason\": \"15 mots maximum\"}" },
      { role: 'user', content: `De: ${from}\nObjet: ${subject}\n\n${text}` }
    ]
  } } };
});

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const src = $('IA ?').all();
return $input.all().map((it, i) => {
  const { from, subject, link, excerpt, lu } = src[i].json;
  let important = true, reason = 'IA indisponible, à vérifier';
  try {
    const r = JSON.parse(it.json.choices[0].message.content);
    important = r.important !== false;
    reason = r.reason || '';
  } catch (e) {}
  return { json: { important, from, subject, link, excerpt, reason, kind: 'ia',
    msg: `📬 <b>${esc(subject)}</b>\nDe : ${esc(from)}\n→ ${esc(reason)}` + (excerpt ? `\n<i>${esc(excerpt)}</i>` : '') + (lu ? '\n👁️ Lu par Kram' : '') + (link ? `\n<a href="${link}">📧 Ouvrir le mail</a>` : '') } };
});

// ponytail: digest lives in workflow static data, capped at 500 entries; a DB table if it must survive n8n data loss
const sd = $getWorkflowStaticData('global');
const add = $input.all().map(({ json: i }) => ({ from: i.from, subject: i.subject, link: i.link || '', kind: i.kind || 'ia', reason: i.reason || '' }));
sd.ignored = (sd.ignored || []).concat(add).slice(-500);
return [];

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const sd = $getWorkflowStaticData('global');
const list = sd.ignored || [];
const traites = sd.traites || 0;
sd.ignored = [];
sd.traites = 0;
const news = {}, ai = [];
for (const i of list) {
  const name = (i.from.match(/^"?([^"<]+?)"?\s*</)?.[1] || i.from).trim();
  if (i.kind === 'newsletter') news[name] = (news[name] || 0) + 1;
  else ai.push(`• ${i.link ? `<a href="${i.link}">${esc(i.subject)}</a>` : esc(i.subject)} — ${esc(name)}\n   ↳ ${esc(i.reason)}`);
}
const nl = Object.entries(news).sort((a, b) => b[1] - a[1]).map(([k, n]) => esc(k) + (n > 1 ? ' ×' + n : ''));
const lines = [`🗞️ <b>Résumé du jour</b> : ${traites} mail(s) traité(s), ${Math.max(0, traites - list.length)} notifié(s), ${list.length} ignoré(s)`];
if (!traites) lines.push('⚠️ Aucun mail traité aujourd\'hui : vérifie que la connexion Gmail fonctionne.');
if (ai.length) lines.push('', '🤖 Jugés peu importants, à vérifier :', ...ai);
if (nl.length) lines.push('', `📰 Newsletters : ${nl.join(', ')}`);
let text = '';
for (const l of lines) { if ((text + l).length > 3800) { text += '\n…(tronqué)'; break; } text += (text ? '\n' : '') + l; }
return [{ json: { text } }];

// ponytail: UIDs kept in workflow static data (last 300); overlapping executions can drop a write
const cutoff = ${IMAP_FROM_UID};
const sd = $getWorkflowStaticData('global');
const seen = sd.seen || [];
const out = $input.all().filter(({ json }) => json.attributes?.uid >= cutoff);
out.forEach(({ json }) => seen.push(json.attributes.uid));
sd.seen = seen.slice(-300);
sd.traites = (sd.traites || 0) + out.length;
return out.map(({ json }) => ({ json: { ...json, lu: false } }));

// ponytail: UIDs kept in workflow static data (last 300); overlapping executions can drop a write
const cutoff = ${IMAP_FROM_UID};
const sd = $getWorkflowStaticData('global');
const seen = sd.seen || [];
const out = $input.all().filter(({ json }) => json.attributes?.uid >= cutoff && !seen.includes(json.attributes.uid));
out.forEach(({ json }) => seen.push(json.attributes.uid));
sd.seen = seen.slice(-300);
sd.traites = (sd.traites || 0) + out.length;
return out.map(({ json }) => ({ json: { ...json, lu: true } }));

